17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Set;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
39	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
40	import org.springframework.samples.petclinic.rest.controller.HouseholdResolver;
41	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.samples.petclinic.util.HashUtils;
50	import org.springframework.samples.petclinic.util.IdentityUtils;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /** Minimal syntactic check for an email address: a non-empty local part, a single
69	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
74	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
75	
76	    /** Disposable email domains that are rejected: an owner whose email domain matches one of
77	     *  these (case-insensitively) is refused with 400. */
78	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
79	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
80	
81	    /** Dedicated audit logger; emits an audit line on successful owner create. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    private final TelephoneNormalizer telephoneNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    private final CityRegionResolver cityRegionResolver;
97	
98	    private final HouseholdResolver householdResolver;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 TelephoneNormalizer telephoneNormalizer,
105	                                 AddressNormalizer addressNormalizer,
106	                                 CityRegionResolver cityRegionResolver,
107	                                 HouseholdResolver householdResolver) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.telephoneNormalizer = telephoneNormalizer;
113	        this.addressNormalizer = addressNormalizer;
114	        this.cityRegionResolver = cityRegionResolver;
115	        this.householdResolver = householdResolver;
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
121	        Collection<Owner> owners;
122	        if (lastName != null) {
123	            owners = this.clinicService.findOwnerByLastName(lastName);
124	        } else {
125	            owners = this.clinicService.findAllOwners();
126	        }
127	        if (owners.isEmpty()) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        if (owner.getRegistrationDate() == null) {
149	            owner.setRegistrationDate(LocalDate.now());
150	        }
151	        // A supplied registration date may not be later than the server's current date.
152	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
156	        LocalDate registrationDate = owner.getRegistrationDate();
157	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
158	            .map(Owner::getRegistrationDate)
159	            .filter(registrationDate::equals)
160	            .count();
161	        if (ownersCreatedThatDay >= 100) {
162	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
163	        }
164	        String address = normalizedAddress(owner);
165	        if (address == null) {
166	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
167	        }
168	        owner.setAddress(address);
169	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
170	        if (telephone == null) {
171	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
172	        }
173	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
174	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
175	        }
176	        owner.setTelephone(telephone);
177	        String email = owner.getEmail();
178	        if (email != null) {
179	            email = email.trim();
180	            if (!EMAIL_PATTERN.matcher(email).matches()) {
181	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
182	            }
183	            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
184	            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
185	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
186	            }
187	            owner.setEmail(email.toLowerCase(Locale.ROOT));
188	        }
189	        // A postcode is optional, but when supplied it must be four digits and valid for the
190	        // owner's city per the fixed region table; a city with no known region accepts any
191	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
192	        String postcode = owner.getPostcode();
193	        if (postcode != null) {
194	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
195	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
196	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	            }
198	        }
199	        // The owner's telephone and email are now in their canonical, stored form.
200	        // The household id is deterministic: owners with the same normalized last name and
201	        // postcode share it automatically. Assign it unconditionally before the duplicate
202	        // checks so both the household-duplicate rule and the identity-key rule key off the
203	        // same computed id.
204	        owner.setHouseholdId(householdResolver.householdId(owner));
205	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
206	        boolean householdMember = householdResolver.householdExists(owner);
207	        // Because the household is keyed on (lastName, postcode), a second owner sharing an
208	        // existing owner's household is a household duplicate and is rejected with 409. The
209	        // 'sharesHousehold' flag only bypasses this block, declaring a deliberate member; it
210	        // no longer creates the link, which the deterministic id now does on its own.
211	        if (householdMember && !sharesHousehold) {
212	            return new ResponseEntity<>(HttpStatus.CONFLICT);
213	        }
214	        if (isDuplicateOwner(owner)) {
215	            return new ResponseEntity<>(HttpStatus.CONFLICT);
216	        }
217	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
218	        long ownersInCity = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
220	            .count();
221	        if (ownersInCity >= 50) {
222	            return new ResponseEntity<>(HttpStatus.CONFLICT);
223	        }
224	        owner.setCustomerCode(customerCode(owner));
225	        owner.setNamesakeCount(namesakeCount(owner));
226	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
227	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
228	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
229	        // still share an existing owner's last name and postcode while carrying a different
230	        // telephone. When it does, it is created but flagged as a possible duplicate of that
231	        // existing owner; otherwise the flag is false and no reference is recorded. A declared
232	        // household member (created via 'sharesHousehold') is not a suspected duplicate, so it
233	        // is never flagged.
234	        Integer possibleDuplicateOf = (sharesHousehold && householdMember) ? null : possibleDuplicateOf(owner);
235	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
236	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
237	        this.clinicService.saveOwner(owner);
238	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
239	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
240	            ownerMapper.membershipLevel(owner), owner.getMembershipNumber());
241	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
242	        headers.setLocation(UriComponentsBuilder.newInstance()
243	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
244	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
245	    }
246	
247	    /**
248	     * The owner's postal address in the single canonical form under which it is stored, or
249	     * {@code null} when the owner supplies no usable address. An owner may supply its address
250	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
251	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
252	     *
253	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
254	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
255	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
256	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
257	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
258	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
259	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
260	     * the caller can reject the request with 400.
261	     *
262	     * <p>This is the single point at which an owner's address is resolved and normalized on
263	     * create, so every rule keyed on the stored address reads the one value produced here.
264	     *
265	     * @param owner the owner about to be created
266	     * @return the canonical stored address, or {@code null} when the owner supplies none
267	     */
268	    private String normalizedAddress(Owner owner) {
269	        String rawLine1 = owner.getAddressLine1();
270	        if (rawLine1 != null && !rawLine1.isBlank()) {
271	            String line1 = addressNormalizer.normalize(rawLine1);
272	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
273	            owner.setAddressLine1(line1);
274	            owner.setAddressLine2(line2.isBlank() ? null : line2);
275	            return line2.isBlank() ? line1 : line1 + " " + line2;
276	        }
277	        owner.setAddressLine1(null);
278	        owner.setAddressLine2(null);
279	        String address = addressNormalizer.normalize(owner.getAddress());
280	        return address.isBlank() ? null : address;
281	    }
282	
283	    /**
284	     * Whether {@code candidate} collides with an already-registered owner under the single
285	     * identity rule enforced on create. This is the one point at which a new owner is
286	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
287	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
288	     * email (or an empty string when absent) and the householdId joined by '|'. The
289	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
290	     * the telephone is part of the key, two members of the same household (same householdId)
291	     * with different telephones have different identityKeys and are both allowed.
292	     *
293	     * <p>The candidate arrives with its telephone and email already normalized and its
294	     * household id already derived, and each existing owner is stored in the same canonical
295	     * form, so an identityKey match means the two owners are genuinely the same identity.
296	     *
297	     * @param candidate the fully-normalized owner about to be created
298	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
299	     */
300	    private boolean isDuplicateOwner(Owner candidate) {
301	        String identityKey = OwnerMapper.identityKey(candidate);
302	        return this.clinicService.findAllOwners().stream()
303	            .filter(existing -> !existing.isDeleted())
304	            .map(OwnerMapper::identityKey)
305	            .anyMatch(identityKey::equals);
306	    }
307	
308	    /**
309	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
310	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
311	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
312	     * postcode while carrying a different telephone — a likely re-registration of the same
313	     * person under a new number. Both must supply a postcode for a match to be possible; when
314	     * several existing owners qualify the lowest id is returned so the result is deterministic.
315	     *
316	     * @param candidate the fully-normalized owner about to be created
317	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
318	     */
319	    private Integer possibleDuplicateOf(Owner candidate) {
320	        String postcode = candidate.getPostcode();
321	        if (postcode == null) {
322	            return null;
323	        }
324	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
325	        return this.clinicService.findAllOwners().stream()
326	            .filter(existing -> !existing.isDeleted()
327	                && IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
328	                && postcode.equals(existing.getPostcode())
329	                && !postcode.isBlank()
330	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
331	            .map(Owner::getId)
332	            .filter(java.util.Objects::nonNull)
333	            .min(Integer::compareTo)
334	            .orElse(null);
335	    }
336	
337	    /**
338	     * Build the customer code assigned to {@code owner} on create, formatted
339	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
340	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
341	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
342	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
343	     *
344	     * <p>When the computed code collides with an already-registered owner's customerCode it is
345	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
346	     * makes it unique (e.g. 'NSW-1A2B3C4D-2'), and the unique code is returned.
347	     */
348	    private String customerCode(Owner owner) {
349	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
350	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
351	        String base = region + "-" + hash8;
352	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
353	            .map(Owner::getCustomerCode)
354	            .filter(java.util.Objects::nonNull)
355	            .collect(java.util.stream.Collectors.toSet());
356	        if (!existing.contains(base)) {
357	            return base;
358	        }
359	        int n = 2;
360	        while (existing.contains(base + "-" + n)) {
361	            n++;
362	        }
363	        return base + "-" + n;
364	    }
365	
366	    /**
367	     * The number of existing owners that share {@code owner}'s firstName and lastName,
368	     * compared case-insensitively. The candidate is not yet stored at the point this is
369	     * assigned, so it does not count itself. This is the value stored as the owner's
370	     * namesakeCount on create.
371	     */
372	    private int namesakeCount(Owner owner) {
373	        return (int) this.clinicService.findAllOwners().stream()
374	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
375	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
376	            .count();
377	    }
378	
379	    /** Fixed list of public holidays that a registration date must roll past. */
380	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
381	        LocalDate.of(2026, 1, 1),
382	        LocalDate.of(2026, 1, 26),
383	        LocalDate.of(2026, 4, 25),
384	        LocalDate.of(2026, 12, 25),
385	        LocalDate.of(2026, 12, 28));
386	
387	    /**
388	     * Roll a registration date forward to the next business day: a Saturday, Sunday
389	     * or listed public holiday advances one day at a time until it lands on a weekday
390	     * that is not a public holiday. A plain weekday is returned unchanged.
391	     */
392	    private static LocalDate toBusinessDay(LocalDate date) {
393	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
394	            date = date.plusDays(1);
395	        }
396	        return date;
397	    }
398	
399	    private static boolean isWeekend(LocalDate date) {
400	        return switch (date.getDayOfWeek()) {
401	            case SATURDAY, SUNDAY -> true;
402	            default -> false;
403	        };
404	    }
405	
406	    /**
407	     * Build the membership number assigned on create, formatted
408	     * {@code '<customerCode>-M<YY>'} where YY is the last two digits of the fiscal year of the
409	     * business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July), e.g.
410	     * 'NSW-1A2B3C4D-M26'.
411	     */
412	    private static String membershipNumber(String customerCode, LocalDate registrationDate) {
413	        String yy = String.format("%02d", OwnerMapper.fiscalYear(registrationDate) % 100);
414	        return customerCode + "-M" + yy;
415	    }
416	
417	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
418	    @Override
419	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
420	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
421	        if (currentOwner == null) {
422	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
423	        }
424	        currentOwner.setAddress(ownerFieldsDto.getAddress());
425	        currentOwner.setCity(ownerFieldsDto.getCity());
426	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
427	        currentOwner.setLastName(ownerFieldsDto.getLastName());
428	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
429	        this.clinicService.saveOwner(currentOwner);
430	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Transactional
435	    @Override
436	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
437	        Owner owner = this.clinicService.findOwnerById(ownerId);
438	        if (owner == null) {
439	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
440	        }
441	        // Soft-delete: flag the owner deleted and retain the row rather than removing it, so it
442	        // is still readable via GET while being ignored by the create duplicate/identity checks.
443	        owner.setDeleted(true);
444	        this.clinicService.saveOwner(owner);
445	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
446	    }
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
451	        Owner owner = this.clinicService.findOwnerById(ownerId);
452	        if (owner == null) {
453	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
454	        }
455	        HttpHeaders headers = new HttpHeaders();
456	        Pet pet = petMapper.toPet(petFieldsDto);
457	        owner.setId(ownerId);
458	        pet.setOwner(owner);
459	        pet.getType().setName(null);
460	        this.clinicService.savePet(pet);
461	        PetDto petDto = petMapper.toPetDto(pet);
462	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
463	            .buildAndExpand(pet.getId()).toUri());
464	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
465	    }
466	
467	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
468	    @Override
469	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
470	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
471	        if (currentOwner != null) {
472	            Pet currentPet = this.clinicService.findPetById(petId);
473	            if (currentPet != null) {
474	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
475	                currentPet.setName(petFieldsDto.getName());
476	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
477	                this.clinicService.savePet(currentPet);
478	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
479	            }
480	        }
481	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
482	    }
483	
484	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
485	    @Override
486	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
487	        HttpHeaders headers = new HttpHeaders();
488	        Visit visit = visitMapper.toVisit(visitFieldsDto);
489	        Pet pet = new Pet();
490	        pet.setId(petId);
491	        visit.setPet(pet);
492	        this.clinicService.saveVisit(visit);
493	        VisitDto visitDto = visitMapper.toVisitDto(visit);
494	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
495	            .buildAndExpand(visit.getId()).toUri());
496	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
497	    }
498	
499	
500	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
501	    @Override
502	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
503	        Owner owner = this.clinicService.findOwnerById(ownerId);
504	        if (owner != null) {
505	            Pet pet = owner.getPet(petId);
506	            if (pet != null) {
507	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
508	            }
509	        }
510	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
511	    }
512	}
