92	    public boolean hasValidNationalNumberLength(String e164Telephone) {
93	        if (e164Telephone == null || !e164Telephone.startsWith("+")) {
94	            return false;
95	        }
96	        String countryCode = countryCodeOf(e164Telephone);
97	        if (countryCode == null) {
