132	            if (i > 0 && i % 3 == 0) {
133	                grouped.append(' ');
134	            }
135	            grouped.append(digits.charAt(i));
136	        }
137	        return grouped.toString();
138	    }
139	
140	    /**
141	     * The listed country code (a key of {@link #NATIONAL_NUMBER_LENGTHS}) that a canonical E.164
142	     * telephone carries, i.e. the one its digits begin with, or {@code null} when the number's
